(()=>{
 const reasonLabels={initial_stock:'Stok awal',inventory_baseline:'Saldo awal riwayat',admin_adjustment:'Penyesuaian admin',order_reserved:'Checkout pesanan',order_expired:'Pesanan kedaluwarsa',payment_failed:'Pembayaran gagal',order_cancelled:'Pesanan dibatalkan'};
 const modal=document.createElement('dialog');modal.className='modal order-modal';modal.id='stockHistoryModal';modal.innerHTML='<div class="modal-inner"><div class="modal-head"><h2 id="stockHistoryTitle">Riwayat stok</h2><button class="close" type="button" aria-label="Tutup">×</button></div><div id="stockHistoryContent" class="order-detail"></div></div>';document.body.append(modal);
 const content=modal.querySelector('#stockHistoryContent');modal.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',event=>{if(event.target===modal)modal.close()});
 const formatDate=value=>new Date(String(value).endsWith('Z')?value:`${value}Z`).toLocaleString('id-ID');
 async function openHistory(id){const product=products.find(item=>item.id===id);document.querySelector('#stockHistoryTitle').textContent=`Riwayat stok · ${product?.name||''}`;content.innerHTML='<div class="empty">Memuat riwayat stok…</div>';modal.showModal();try{const data=await api(`/api/products/${id}/stock-movements`);content.innerHTML=`<div class="order-box"><small>Stok saat ini</small><strong>${data.product.stock} unit</strong></div>${data.movements.length?`<div class="order-lines">${data.movements.map(item=>`<div class="order-line"><span><strong>${escapeHtml(reasonLabels[item.reason]||item.reason)}</strong><small>${formatDate(item.createdAt)}${item.orderId?` · #${escapeHtml(item.orderId)}`:''}</small>${item.note?`<small>${escapeHtml(item.note)}</small>`:''}</span><span style="text-align:right"><strong style="color:${item.changeQty>0?'#207044':'#a33'}">${item.changeQty>0?'+':''}${item.changeQty}</strong><small>${item.stockBefore} → ${item.stockAfter}</small></span></div>`).join('')}</div>`:'<div class="empty">Belum ada perubahan stok yang tercatat.</div>'}`}catch(error){content.innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}
 function addButtons(){document.querySelectorAll('#productRows .edit-product').forEach(edit=>{if(edit.parentElement.querySelector('.stock-history'))return;const button=document.createElement('button');button.type='button';button.className='icon-btn stock-history';button.dataset.id=edit.dataset.id;button.textContent='Riwayat';button.style.marginLeft='8px';button.addEventListener('click',()=>openHistory(Number(button.dataset.id)));edit.after(button)})}
 const rows=document.querySelector('#productRows');if(rows){new MutationObserver(addButtons).observe(rows,{childList:true});addButtons()}
})();
